{"content":"import datetime
import unittest

from daterange import parse_range

D = datetime.date


class TestDateRanges(unittest.TestCase):
    """SPEC.md item 1: A..B where both sides are ISO dates."""

    def test_two_dates(self):
        self.assertEqual(parse_range("2026-10-01..2026-10-31"), (D(2026, 10, 1), D(2026, 10, 31)))

    def test_result_is_a_pair_of_dates(self):
        start, end = parse_range("2026-10-01..2026-10-31")
        self.assertIsInstance(start, datetime.date)
        self.assertIsInstance(end, datetime.date)

    def test_single_day_range(self):
        self.assertEqual(parse_range("2026-10-05..2026-10-05"), (D(2026, 10, 5), D(2026, 10, 5)))

    def test_leap_day(self):
        self.assertEqual(parse_range("2024-02-29..2024-02-29"), (D(2024, 2, 29), D(2024, 2, 29)))

    def test_range_across_years(self):
        self.assertEqual(parse_range("2026-12-30..2027-01-02"), (D(2026, 12, 30), D(2027, 1, 2)))


class TestMonthRanges(unittest.TestCase):
    """SPEC.md item 2: YYYY-MM is the whole month, first to last day."""

    def test_february(self):
        self.assertEqual(parse_range("2026-02"), (D(2026, 2, 1), D(2026, 2, 28)))

    def test_leap_february(self):
        self.assertEqual(parse_range("2024-02"), (D(2024, 2, 1), D(2024, 2, 29)))

    def test_december(self):
        self.assertEqual(parse_range("2026-12"), (D(2026, 12, 1), D(2026, 12, 31)))

    def test_thirty_day_month(self):
        self.assertEqual(parse_range("2026-04"), (D(2026, 4, 1), D(2026, 4, 30)))

    def test_month_range_spans_first_to_last_day(self):
        self.assertEqual(parse_range("2026-02..2026-04"), (D(2026, 2, 1), D(2026, 4, 30)))

    def test_month_range_inside_one_year(self):
        self.assertEqual(parse_range("2025-11..2026-01"), (D(2025, 11, 1), D(2026, 1, 31)))


class TestWeekRanges(unittest.TestCase):
    """SPEC.md item 3: YYYY-Www is Monday to Sunday of that ISO week."""

    def test_iso_week(self):
        self.assertEqual(parse_range("2026-W44"), (D(2026, 10, 26), D(2026, 11, 1)))

    def test_first_week_starts_in_previous_year(self):
        self.assertEqual(parse_range("2026-W01"), (D(2025, 12, 29), D(2026, 1, 4)))

    def test_week_53_exists(self):
        self.assertEqual(parse_range("2026-W53"), (D(2026, 12, 28), D(2027, 1, 3)))

    def test_week_range(self):
        self.assertEqual(parse_range("2026-W44..2026-W46"), (D(2026, 10, 26), D(2026, 11, 15)))


class TestYearRanges(unittest.TestCase):
    """SPEC.md item 4: YYYY is the whole year."""

    def test_year(self):
        self.assertEqual(parse_range("2026"), (D(2026, 1, 1), D(2026, 12, 31)))

    def test_leap_year(self):
        self.assertEqual(parse_range("2024"), (D(2024, 1, 1), D(2024, 12, 31)))

    def test_year_range(self):
        self.assertEqual(parse_range("2025..2026"), (D(2025, 1, 1), D(2026, 12, 31)))


class TestOpenEnds(unittest.TestCase):
    """SPEC.md item 5: open ends, and '..' on its own is an error."""

    def test_open_start(self):
        self.assertEqual(parse_range("..2026-10-31"), (None, D(2026, 10, 31)))

    def test_open_end(self):
        self.assertEqual(parse_range("2026-10-01.."), (D(2026, 10, 1), None))

    def test_open_start_uses_last_day_of_unit(self):
        self.assertEqual(parse_range("..2026-10"), (None, D(2026, 10, 31)))
        self.assertEqual(parse_range("..2026-W44"), (None, D(2026, 11, 1)))
        self.assertEqual(parse_range("..2026"), (None, D(2026, 12, 31)))

    def test_open_end_uses_first_day_of_unit(self):
        self.assertEqual(parse_range("2026-10.."), (D(2026, 10, 1), None))
        self.assertEqual(parse_range("2026-W44.."), (D(2026, 10, 26), None))
        self.assertEqual(parse_range("2026.."), (D(2026, 1, 1), None))

    def test_open_end_with_spaces(self):
        self.assertEqual(parse_range("  .. 2026-10-31  "), (None, D(2026, 10, 31)))

    def test_bare_separator_is_error(self):
        for text in ("..", " .. ", "  ..", "..  ", "\t..\n", "...."):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)


class TestOrdering(unittest.TestCase):
    """SPEC.md item 6: B before A is an error, equal bounds are fine."""

    def test_end_before_start(self):
        with self.assertRaises(ValueError):
            parse_range("2026-10-31..2026-10-01")

    def test_month_end_before_month_start(self):
        with self.assertRaises(ValueError):
            parse_range("2026-11..2026-10")

    def test_units_compared_by_span(self):
        with self.assertRaises(ValueError):
            parse_range("2026..2025")

    def test_identical_bounds_are_allowed(self):
        self.assertEqual(parse_range("2026-10-05..2026-10-05"), (D(2026, 10, 5), D(2026, 10, 5)))
        self.assertEqual(parse_range("2026-W44..2026-W44"), (D(2026, 10, 26), D(2026, 11, 1)))
        self.assertEqual(parse_range("2026..2026"), (D(2026, 1, 1), D(2026, 12, 31)))

    def test_start_before_end_returns_ordered_pair(self):
        start, end = parse_range("2025-03..2026-02")
        self.assertLess(start, end)


class TestWhitespace(unittest.TestCase):
    """SPEC.md item 7: spaces around the text or around '..' are fine."""

    def test_spaces_around_text(self):
        self.assertEqual(parse_range("  2026-10-01..2026-10-31  "), (D(2026, 10, 1), D(2026, 10, 31)))

    def test_spaces_around_separator(self):
        self.assertEqual(parse_range("2026-10-01 .. 2026-10-31"), (D(2026, 10, 1), D(2026, 10, 31)))

    def test_spaces_everywhere(self):
        self.assertEqual(parse_range("\t 2026-02 .. 2026-04 \n"), (D(2026, 2, 1), D(2026, 4, 30)))

    def test_spaces_do_not_change_unit_bounds(self):
        self.assertEqual(parse_range(" 2026-W44 "), (D(2026, 10, 26), D(2026, 11, 1)))


class TestMalformed(unittest.TestCase):
    """SPEC.md item 7: anything else malformed is an error."""

    def assert_rejected(self, texts):
        for text in texts:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_empty(self):
        self.assert_rejected(["", "   ", "\t\n"])

    def test_out_of_range_values(self):
        self.assert_rejected([
            "2026-13",              # month 13
            "2026-00",              # month 0
            "2026-13-01",           # month 13 in a full date
            "2026-02-30",           # day beyond the end of February
            "2023-02-29",           # not a leap year
            "2026-04-31",           # day beyond the end of April
            "2026-W54",             # no ISO week 54
            "2026-W00",             # weeks start at 1
            "2025-W53",             # 2025 has only 52 ISO weeks
        ])

    def test_wrong_shape(self):
        self.assert_rejected([
            "2026-1",               # month needs two digits
            "2026-1-1",             # date needs two-digit month and day
