class TestMalformed(unittest.TestCase):
    """SPEC.md item 7: anything else malformed is an error."""

    def assert_rejected(self, texts):
        for text in texts:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_empty(self):
        self.assert_rejected(["", "   ", "\t\n"])

    def test_out_of_range_values(self):
        self.assert_rejected([
            "2026-13",              # month 13
            "2026-00",              # month 0
            "2026-13-01",           # month 13 in a full date
            "2026-02-30",           # day beyond the end of February
            "2023-02-29",           # not a leap year
            "2026-04-31",           # day beyond the end of April
            "2026-W54",             # no ISO week 54
            "2026-W00",             # weeks start at 1
            "2025-W53",             # 2025 has only 52 ISO weeks
        ])

    def test_wrong_shape(self):
        self.assert_rejected([
            "2026-1",               # month needs two digits
            "2026-1-1",             # date needs two-digit month and day
            "20261001",             # no separators
            "2026-10-1",            # day needs two digits
            "26-10-01",             # year needs four digits
            "2026-W4",              # week needs two digits
            "2026-w44",             # ISO weeks use a capital W
            "2026/10/01",
            "10-01-2026",
            "2026-",
            "2026-W",
        ])

    def test_not_a_value(self):
        self.assert_rejected(["abc", "today", "-2026", "2026-10-01x", "x2026"])

    def test_malformed_sides(self):
        self.assert_rejected([
            "2026-10-01..nope",
            "nope..2026-10-01",
            "2026-10-01..2026-13",
            "2026-W54..2026-W44",
            "..garbage",
        ])

    def test_separator_misuse(self):
        self.assert_rejected([
            "2026-10-01...2026-10-31",
            "2026-10-01..2026-10-31..2026-11-01",
            "2026-10-01 . 2026-10-31",
            "2026-10-01.2026-10-31",
        ])

    def test_non_string_input(self):
        self.assert_rejected([None, 2026, datetime.date(2026, 10, 1)])


